import{_ as t,o as d,c as n,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"CLI reference","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cli.md","filePath":"guide/cli.md"}'),a={name:"guide/cli.md"};function i(o,e,r,c,l,h){return d(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><p>The <code>frensense</code> binary is the single entry point for the engine.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>frensense [path]</code></td><td>Scan a file or directory and print findings.</td></tr><tr><td><code>frensense watch [path]</code></td><td>Watch mode: re-scan changed files, print only new findings.</td></tr><tr><td><code>frensense mcp</code></td><td>Run the MCP server (stdio, newline-delimited JSON-RPC) for AI agents.</td></tr><tr><td><code>frensense lsp</code></td><td>Run the LSP server (stdio, Content-Length framing) for editors.</td></tr><tr><td><code>frensense bundle [&lt;corpus&gt;] [out.frc]</code></td><td>Compile twin-example families into a <code>.frc</code> knowledge bundle.</td></tr><tr><td><code>frensense bundle info &lt;file.frc&gt;</code></td><td>Inspect a bundle&#39;s metadata and facts.</td></tr><tr><td><code>frensense lint &lt;corpus&gt;</code></td><td>Check corpus families before they are bundled: layout, metadata, class, provenance, diversity, and teachability. <code>--strict</code>, <code>--json</code>, <code>--coverage</code>, <code>--no-gate</code>, <code>--classes</code>, <code>--advisories</code>, <code>--require-heldout</code>. Exit <code>0</code> clean, <code>1</code> issues, <code>2</code> bad configuration.</td></tr><tr><td><code>frensense explain [&lt;rule-id&gt;] [-b &lt;bundle&gt;]</code></td><td>Describe one rule (id, CWE, why, fix); no id lists every rule. <code>-b</code> also describes bundle-learned rules. A directory literally named <code>explain</code> is still scannable — flags are the unambiguous form.</td></tr></tbody></table><p>One binary carries all of this; there is no separate MCP or LSP package.</p><h3 id="paths-vs-subcommands" tabindex="-1">Paths vs subcommands <a class="header-anchor" href="#paths-vs-subcommands" aria-label="Permalink to &quot;Paths vs subcommands&quot;">​</a></h3><p>A path named like a subcommand wins, so a repo containing <code>mcp/</code>, <code>watch/</code> or <code>bundle/</code> stays scannable with the bare token. Arguments only the subcommand understands keep it claimed, and each mode has an unambiguous form:</p><table tabindex="0"><thead><tr><th>Invocation</th><th>Result when a same-named path exists</th></tr></thead><tbody><tr><td><code>frensense mcp</code></td><td>Scans <code>./mcp</code>. <code>frensense --mcp</code> starts the server.</td></tr><tr><td><code>frensense watch</code></td><td>Scans <code>./watch</code>. <code>frensense watch &lt;path&gt;</code> enters watch mode.</td></tr><tr><td><code>frensense bundle</code></td><td>Scans <code>./bundle</code>. <code>frensense bundle &lt;corpus&gt; [out.frc]</code> compiles.</td></tr><tr><td><code>frensense lint</code></td><td>Scans <code>./lint</code>. <code>frensense lint &lt;corpus&gt;</code> lints; <code>frensense lint --help</code> explains the subcommand&#39;s own flags.</td></tr><tr><td><code>frensense explain</code></td><td>Scans <code>./explain</code>. <code>frensense --list-rules</code> lists rules.</td></tr></tbody></table><p>Only argv[1] names a subcommand — <code>frensense . mcp</code> scans both paths — and <code>lsp</code> is always the server, since editors run <code>frensense lsp</code> non-interactively where a silent scan would be a break, not an ambiguity.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--github</code></td><td>Emit GitHub Actions workflow commands (<code>::error</code>/<code>::warning</code>) per finding.</td></tr><tr><td><code>--corpus-bundle &lt;file&gt;</code></td><td>Load a <code>.frc</code> knowledge bundle into the engine for this scan.</td></tr><tr><td><code>--emit-baseline &lt;file&gt;</code></td><td>Write the current finding fingerprints as a baseline.</td></tr><tr><td><code>--compare-baseline &lt;file&gt;</code></td><td>Only report findings that are new relative to the baseline.</td></tr><tr><td><code>--language &lt;lang&gt;</code></td><td>Restrict scanning to one language (<code>rust</code>, <code>typescript</code>, <code>javascript</code>, <code>python</code>).</td></tr><tr><td>severity / confidence filters</td><td>Limit output to findings above a threshold.</td></tr><tr><td><code>--show-flows</code></td><td>Print the source→sink flow with each step&#39;s location in text output.</td></tr><tr><td><code>--explain</code></td><td>List sink arguments that produced no advisory, with the reason.</td></tr><tr><td><code>--diff-only</code></td><td>Report only findings on lines changed since the last commit. Changed files are still scanned whole (a diff can make an old line reachable), but findings at unchanged lines are pre-existing: they are counted and suppressed, not reported. Track them with <code>--compare-baseline</code>.</td></tr><tr><td><code>--mcp</code></td><td>Run the MCP server unconditionally, even when a path named <code>mcp</code> exists.</td></tr><tr><td><code>--list-rules</code></td><td>List every rule id: built-in, plus the bundle&#39;s learned rules when <code>-b</code> is given. Unambiguous form of <code>frensense explain</code> with no id.</td></tr><tr><td><code>--explain-rule &lt;id&gt;</code></td><td>Describe one rule. Unambiguous form of <code>frensense explain &lt;rule-id&gt;</code>, for when a path named <code>explain</code> exists.</td></tr></tbody></table><p>Every finding reports a stable rule id (<code>taint.sql-injection</code>, <code>check.weak-hash</code>, <code>policy.&lt;id&gt;</code>) and its CWE, so <code>frensense explain &lt;rule-id&gt;</code> is the fastest way to see what a finding means and how to fix it:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ frensense explain taint.path-traversal</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">taint.path-traversal  Path traversal</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  CWE:  CWE-22  https://cwe.mitre.org/data/definitions/22.html</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  why:  Attacker-supplied path segments can reach files outside the intended directory.</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  fix:  Resolve the path, then check it stays inside the allowed base directory; prefer fixed names.</span></span></code></pre></div><p>Built-in rules carry a card; bundle-learned rules carry their data instead — trigger, requirements, message — so the bundle that taught the rule is its documentation. Pass <code>-b</code> to describe one, or to list them all:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ frensense explain policy.redirect-challenge -b learned.frc</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">policy.redirect-challenge  Learned policy (from learned.frc)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  severity: warning</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  trigger:  call to \`redirect\`</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  scope:    same function</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  requires: guard call \`challenge_ok\` is present</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  why:  open redirects bypass the challenge</span></span></code></pre></div><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>FRENSENSE_CORPUS_BUNDLE</code></td><td>Default <code>.frc</code> bundle for MCP/LSP scans.</td></tr></tbody></table>`,17)])])}const f=t(a,[["render",i]]);export{u as __pageData,f as default};
